Lemma fsz_min6 : forall k, 0 <= k <= KMAX -> fsz (Z.min k 6) = Z.min (fsz k) 4096.
Proof. intros k Hk. destruct (class_cases k Hk) as [C|[C|[C|[C|[C|[C|[C|C]]]]]]]; destruct C as (-> & _); reflexivity. Qed.

